questionvariables.text:
/*prob*/
toffee:rand(5)+2;
total_toffs:toffee+3;
chestnut:rand_with_step(1,5,1);
chestnuts:rand_with_prohib(5,9,[toffee,total_toffs]);
berries:rand_with_prohib(2,5,[toffee,chestnut]);
total_berries:rand_with_prohib(6,10,[chestnuts,total_toffs]);

/*worked solution variables*/
sol1:binomial(total_toffs,toffee);
sol2:binomial(chestnuts,chestnut);
sol3:binomial(total_berries,berries);
ta:sol1*sol2*sol3;
